INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7116198, 1086992, 117534, '<td valign="top">Awesome!</td>', 'Awesome!', '2013-10-16 01:08:46.000000', NULL, 1),
(7116209, 1086734, 117534, '<td valign="top">Holy buckets WOW</td>', 'Holy buckets WOW', '2013-10-16 01:20:42.000000', NULL, 1),
(7116219, 1086999, 30861, '<td valign="top">Beautifully processed. The bit of grain/noise is an asset for the mood here. The separation of the head from the background is skillfully done. For my tastes, the crop is bit too tight on the bottom.<br/> <br/>As far as relevance to the novel, "Please sir, may I have some more?" is the obvious reference, and it does work, but a couple things keep it from being as strong as it might be, for me: the spoon''s too nice, and the bowl and spoon both should show evidence of a first serving consumed. Also, somewhat parenthetically, the white cuff is too clean and too white, if you think about it.<br/> <br/>But, in the main, very nicely done. It goes in my 7 group for now, may get bumped or not depending on what else I find in this challenge :-)<br/><br/><i>Message edited by author 2013-10-23 00:12:25.</i></td>', 'Beautifully processed. The bit of grain/noise is an asset for the mood here. The separation of the head from the background is skillfully done. For my tastes, the crop is bit too tight on the bottom. As far as relevance to the novel, "Please sir, may I have some more?" is the obvious reference, and it does work, but a couple things keep it from being as strong as it might be, for me: the spoon''s too nice, and the bowl and spoon both should show evidence of a first serving consumed. Also, somewhat parenthetically, the white cuff is too clean and too white, if you think about it. But, in the main, very nicely done. It goes in my 7 group for now, may get bumped or not depending on what else I find in this challenge :-)', '2013-10-16 01:29:24.000000', '2013-10-23 01:12:25.000000', 1),
(7116223, 1087044, 30861, '<td valign="top">The title of the novel is "Go tell it on the Mountain", and it explores the role of the Christian church in the lives of African-Americans. The referenced mountain is Mount Sinai, where Moses brought down the commandments.<br/> <br/>So for me, this otherwise charming, misty mountainscape is sort of irrelevant to the challenge, and I''m giving it a 5. It''s not engaging me at any higher level.</td>', 'The title of the novel is "Go tell it on the Mountain", and it explores the role of the Christian church in the lives of African-Americans. The referenced mountain is Mount Sinai, where Moses brought down the commandments. So for me, this otherwise charming, misty mountainscape is sort of irrelevant to the challenge, and I''m giving it a 5. It''s not engaging me at any higher level.', '2013-10-16 01:34:12.000000', NULL, 1),
(7116228, 1087222, 30861, '<td valign="top">Something''s really wrong with the relationship of the airbrushed skirt and the car. I can''t tell if she''s been pasted in, or whether it''s just generally crappy masking for the soft blur. It just looks REALLY wrong...<br/> <br/>Otherwise, it''s an amusing take on Gatsby, though of course the car is way out of period. What IS that car anyway? I ought to know, with thise louvers, but I''m drawing a blank.<br/> <br/>Anyway, for me it''s a 4 vote.</td>', 'Something''s really wrong with the relationship of the airbrushed skirt and the car. I can''t tell if she''s been pasted in, or whether it''s just generally crappy masking for the soft blur. It just looks REALLY wrong... Otherwise, it''s an amusing take on Gatsby, though of course the car is way out of period. What IS that car anyway? I ought to know, with thise louvers, but I''m drawing a blank. Anyway, for me it''s a 4 vote.', '2013-10-16 01:40:22.000000', NULL, 1),
(7116234, 1087162, 117534, '<td valign="top">OOOOOO LOVE LOVE this!!!!  BTY did I tell you how much I love this... AGAIN</td>', 'OOOOOO LOVE LOVE this!!!!  BTY did I tell you how much I love this... AGAIN', '2013-10-16 01:48:40.000000', NULL, 1),
