(7116716, 1086734, 124982, '<td valign="top">Holy smokes, man! This is beautiful! How majestic and MAGIC indeed! You nailed this shot, and what a challenge it mustve been to capture the tonal range! Top 3 no doubt!</td>', 'Holy smokes, man! This is beautiful! How majestic and MAGIC indeed! You nailed this shot, and what a challenge it mustve been to capture the tonal range! Top 3 no doubt!', '2013-10-16 19:54:53.000000', NULL, 1),
(7116718, 1087112, 124982, '<td valign="top">Great idea, great composition, great lighting! Overall, just a great shot!</td>', 'Great idea, great composition, great lighting! Overall, just a great shot!', '2013-10-16 19:55:56.000000', NULL, 1),
(7116719, 1086987, 124982, '<td valign="top">Let it be known I''m a sucker for color and blur. This is just gorgeous! Beautifully saturated and love the sense of motion! Very nice!</td>', 'Let it be known I''m a sucker for color and blur. This is just gorgeous! Beautifully saturated and love the sense of motion! Very nice!', '2013-10-16 19:56:40.000000', NULL, 1),
