(7117126, 1087000, 134859, '<td valign="top">I really enjoy the softness of this photo.  <br/>The colors give it a vintage/retro feel.  <br/>Never heard of the title.  <br/>Gave it a 6</td>', 'I really enjoy the softness of this photo.  The colors give it a vintage/retro feel.  Never heard of the title.  Gave it a 6', '2013-10-17 10:33:21.000000', NULL, 1),
