(7118444, 1087102, 59029, '<td valign="top">wish there was more here than just an abandoned building.</td>', 'wish there was more here than just an abandoned building.', '2013-10-19 14:08:40.000000', NULL, 1),
(7118445, 1086700, 94815, '<td valign="top">Only knowing the book from its synopsis, this seems an appropriate enough reference to the story. It''s also photographed well with appealing tones, tint and texture.  The composition is very static and carefully arranged, but to my eye, the balance is a little off - too heavy on the left which could be easily fixed by a slight crop from the right. Unless, however, you are trying for some instability in which case a different composition would work better.. So the overall effect is not satisfying. To break it down, it''s a 6 for content, 6 for technique but only a 5 for visual impact. So, it squeaks by with a 6.</td>', 'Only knowing the book from its synopsis, this seems an appropriate enough reference to the story. It''s also photographed well with appealing tones, tint and texture.  The composition is very static and carefully arranged, but to my eye, the balance is a little off - too heavy on the left which could be easily fixed by a slight crop from the right. Unless, however, you are trying for some instability in which case a different composition would work better.. So the overall effect is not satisfying. To break it down, it''s a 6 for content, 6 for technique but only a 5 for visual impact. So, it squeaks by with a 6.', '2013-10-19 14:09:43.000000', NULL, 1),
(7118446, 1087222, 59029, '<td valign="top">This is only an Advanced challenge, not Expert.  Nice concept but clumsy execution.</td>', 'This is only an Advanced challenge, not Expert.  Nice concept but clumsy execution.', '2013-10-19 14:10:25.000000', NULL, 1),
