(7118711, 1086157, 8759, '<td valign="top">A well executed picture that does not tell me much. 6 <br/> <br/>I am not an expert but does not look like a fly fishing spot (I might be wrong)</td>', 'A well executed picture that does not tell me much. 6  I am not an expert but does not look like a fly fishing spot (I might be wrong)', '2013-10-19 22:01:53.000000', NULL, 1),
(7118712, 1086744, 8759, '<td valign="top">One of the better web entries but still nothing exceptional. The water drops are fine but the spider itself lacks something. Might not be anything you could do. I would have tried to have more green in the background. 5</td>', 'One of the better web entries but still nothing exceptional. The water drops are fine but the spider itself lacks something. Might not be anything you could do. I would have tried to have more green in the background. 5', '2013-10-19 22:05:50.000000', NULL, 1),
(7118714, 1087057, 8759, '<td valign="top">Nicely composed, well balanced, good autumn colors. Would have been nice to have a person in the frame. For me is a 5</td>', 'Nicely composed, well balanced, good autumn colors. Would have been nice to have a person in the frame. For me is a 5', '2013-10-19 22:10:24.000000', NULL, 1),
(7118715, 1086979, 8759, '<td valign="top">I like the processing and the colors. It makes look out of this world to a certain extent. The tilt however ruins it. The grass on the bottom mid-left is a bit too much too. 5</td>', 'I like the processing and the colors. It makes look out of this world to a certain extent. The tilt however ruins it. The grass on the bottom mid-left is a bit too much too. 5', '2013-10-19 22:13:20.000000', NULL, 1),
